func  (this *probit) ParseDepositWithdrawFee(fee interface{}, optionalArgs ...interface{}) interface{}  {
    //
    // {
    //     "id": "USDT",
    //     "display_name": { "ko-kr": '테더', "en-us": "Tether" },
    //     "show_in_ui": true,
    //     "platform": [
    //       {
    //         "id": "ETH",
    //         "priority": "1",
    //         "deposit": true,
    //         "withdrawal": true,
    //         "currency_id": "USDT",
    //         "precision": "6",
    //         "min_confirmation_count": "15",
    //         "require_destination_tag": false,
    //         "allow_withdrawal_destination_tag": false,
    //         "display_name": [Object],
    //         "min_deposit_amount": "0",
    //         "min_withdrawal_amount": "1",
    //         "withdrawal_fee": [Array],
    //         "deposit_fee": {},
    //         "suspended_reason": '',
    //         "deposit_suspended": false,
    //         "withdrawal_suspended": false,
    //         "platform_currency_display_name": [Object]
    //       },
    //     ],
    //     "internal_transfer": { suspended_reason: null, suspended: false },
    //     "stakeable": false,
    //     "unstakeable": false,
    //     "auto_stake": false,
    //     "auto_stake_amount": "0"
    //   }
    //
    currency := ccxt.GetArg(optionalArgs, 0, nil)
    _ = currency
    var depositWithdrawFee interface{} = this.DepositWithdrawFee(map[string]interface{} {})
    var platforms interface{} = this.SafeValue(fee, "platform", []interface{}{})
    var depositResult interface{} = map[string]interface{} {
        "fee": nil,
        "percentage": nil,
    }
    for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(platforms)); i++ {
        var network interface{} = ccxt.GetValue(platforms, i)
        var networkId interface{} = this.SafeString(network, "id")
        var networkCode interface{} = this.NetworkIdToCode(networkId, ccxt.GetValue(currency, "code"))
        var withdrawalFees interface{} = this.SafeValue(network, "withdrawal_fee", map[string]interface{} {})
        var withdrawFee interface{} = this.SafeNumber(ccxt.GetValue(withdrawalFees, 0), "amount")
        if ccxt.IsTrue(ccxt.GetArrayLength(withdrawalFees)) {
            var withdrawResult interface{} = map[string]interface{} {
                "fee": withdrawFee,
                "percentage": ccxt.Ternary(ccxt.IsTrue((!ccxt.IsEqual(withdrawFee, nil))), false, nil),
            }
            if ccxt.IsTrue(ccxt.IsEqual(i, 0)) {
                ccxt.AddElementToObject(depositWithdrawFee, "withdraw", withdrawResult)
            }
            ccxt.AddElementToObject(ccxt.GetValue(depositWithdrawFee, "networks"), networkCode, map[string]interface{} {
    "withdraw": withdrawResult,
    "deposit": depositResult,
})
        }
    }
    ccxt.AddElementToObject(depositWithdrawFee, "info", fee)
    return depositWithdrawFee
}
func  (this *probit) Nonce() interface{}  {
    return this.Milliseconds()
}
func  (this *probit) Sign(path interface{}, optionalArgs ...interface{}) interface{}  {
    api := ccxt.GetArg(optionalArgs, 0, "public")
    _ = api
    method := ccxt.GetArg(optionalArgs, 1, "GET")
    _ = method
    params := ccxt.GetArg(optionalArgs, 2, map[string]interface{} {})
    _ = params
    headers := ccxt.GetArg(optionalArgs, 3, nil)
    _ = headers
    body := ccxt.GetArg(optionalArgs, 4, nil)
    _ = body
    var url interface{} = ccxt.Add(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), api), "/")
    var query interface{} = this.Omit(params, this.ExtractParams(path))
    if ccxt.IsTrue(ccxt.IsEqual(api, "accounts")) {
        this.CheckRequiredCredentials()
        url = ccxt.Add(url, this.ImplodeParams(path, params))
        var auth interface{} = ccxt.Add(ccxt.Add(this.ApiKey, ":"), this.Secret)
        var auth64 interface{} = this.StringToBase64(auth)
        headers = map[string]interface{} {
            "Authorization": ccxt.Add("Basic ", auth64),
            "Content-Type": "application/json",
        }
        if ccxt.IsTrue(ccxt.GetArrayLength(ccxt.ObjectKeys(query))) {
            body = this.Json(query)
        }
    } else {
        url = ccxt.Add(url, ccxt.Add(this.Version, "/"))
        if ccxt.IsTrue(ccxt.IsEqual(api, "public")) {
            url = ccxt.Add(url, this.ImplodeParams(path, params))
            if ccxt.IsTrue(ccxt.GetArrayLength(ccxt.ObjectKeys(query))) {
                url = ccxt.Add(url, ccxt.Add("?", this.Urlencode(query)))
            }
        } else if ccxt.IsTrue(ccxt.IsEqual(api, "private")) {
            var now interface{} = this.Milliseconds()
            this.CheckRequiredCredentials()
            var expires interface{} = this.SafeInteger(this.Options, "expires")
            if ccxt.IsTrue(ccxt.IsTrue((ccxt.IsEqual(expires, nil))) || ccxt.IsTrue((ccxt.IsLessThan(expires, now)))) {
                panic(ccxt.AuthenticationError(ccxt.Add(this.Id, " access token expired, call signIn() method")))
            }
            var accessToken interface{} = this.SafeString(this.Options, "accessToken")
            headers = map[string]interface{} {
                "Authorization": ccxt.Add("Bearer ", accessToken),
            }
            url = ccxt.Add(url, this.ImplodeParams(path, params))
            if ccxt.IsTrue(ccxt.IsEqual(method, "GET")) {
                if ccxt.IsTrue(ccxt.GetArrayLength(ccxt.ObjectKeys(query))) {
                    url = ccxt.Add(url, ccxt.Add("?", this.Urlencode(query)))
                }
            } else if ccxt.IsTrue(ccxt.GetArrayLength(ccxt.ObjectKeys(query))) {
                body = this.Json(query)
                ccxt.AddElementToObject(headers, "Content-Type", "application/json")
            }
        }
    }
    return map[string]interface{} {
        "url": url,
        "method": method,
        "body": body,
        "headers": headers,
    }
}
/**
 * @method
 * @name probit#signIn
 * @see https://docs-en.probit.com/reference/token
 * @description sign in, must be called prior to using other authenticated methods
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns response from exchange
 */
func  (this *probit) SignIn(optionalArgs ...interface{}) <- chan interface{} {
            ch := make(chan interface{})
            go func() interface{} {
                defer close(ch)
                defer ccxt.ReturnPanicError(ch)
                    params := ccxt.GetArg(optionalArgs, 0, map[string]interface{} {})
            _ = params
            this.CheckRequiredCredentials()
            var request interface{} = map[string]interface{} {
                "grant_type": "client_credentials",
            }
        
            response:= (<-this.AccountsPostToken(this.Extend(request, params)))
            ccxt.PanicOnError(response)
            //
            //     {
            //         "access_token": "0ttDv/2hTTn3bLi8GP1gKaneiEQ6+0hOBenPrxNQt2s=",
            //         "token_type": "bearer",
            //         "expires_in": 900
            //     }
            //
            var expiresIn interface{} = this.SafeInteger(response, "expires_in")
            var accessToken interface{} = this.SafeString(response, "access_token")
            ccxt.AddElementToObject(this.Options, "accessToken", accessToken)
            ccxt.AddElementToObject(this.Options, "expires", this.Sum(this.Milliseconds(), ccxt.Multiply(expiresIn, 1000)))
        
            ch <- response
            return nil
        
            }()
            return ch
        }
func  (this *probit) HandleErrors(code interface{}, reason interface{}, url interface{}, method interface{}, headers interface{}, body interface{}, response interface{}, requestHeaders interface{}, requestBody interface{}) interface{}  {
    if ccxt.IsTrue(ccxt.IsEqual(response, nil)) {
        return nil  // fallback to default error handler
    }
    if ccxt.IsTrue(ccxt.InOp(response, "errorCode")) {
        var errorCode interface{} = this.SafeString(response, "errorCode")
        if ccxt.IsTrue(!ccxt.IsEqual(errorCode, nil)) {
            var errMessage interface{} = this.SafeString(response, "message", "")
            var details interface{} = this.SafeValue(response, "details")
            var feedback interface{} = ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(this.Id, " "), errorCode), " "), errMessage), " "), this.Json(details))
            if ccxt.IsTrue(ccxt.InOp(this.Exceptions, "exact")) {
                this.ThrowExactlyMatchedException(ccxt.GetValue(this.Exceptions, "exact"), errorCode, feedback)
            }
            if ccxt.IsTrue(ccxt.InOp(this.Exceptions, "broad")) {
                this.ThrowBroadlyMatchedException(ccxt.GetValue(this.Exceptions, "broad"), errMessage, feedback)
            }
            panic(ccxt.ExchangeError(feedback))
        }
    }
    return nil
}


func (this *probit) Init(userConfig map[string]interface{}) {
    this.Exchange = ccxt.Exchange{}
    this.Exchange.DerivedExchange = this
    this.Exchange.InitParent(userConfig, this.Describe().(map[string]interface{}), this)
}
